import { AtlasAttachmentLoader, SkeletonBinary, SkeletonData, SkeletonJson, TextureAtlas } from '@esotericsoftware/spine-pixi-v8';
import { Assets, Texture, Spritesheet, UnresolvedAsset, BitmapFont } from 'pixi.js';

import { IAnimationAssetConfig, IAssetConfig, IAssetList, IBaseAssetConfig, ISpriteSheetAssetConfig, LazyAssetKeys } from './types';
import { SoundMap } from './sounds';
import { SoundLoader } from './sounds/loader';

type AssetLoaderConfig = Parameters<typeof Assets.load>[0];

export class AssetManager {
    public static animations: { [key: string]: SkeletonData };
    public static sounds: SoundMap = {};
    public static onProgressChange: ((perc: number) => void) | null;
    public static readonly skeletonCache: Record<string, SkeletonData> = Object.create(null);
    private static textureKeys: string[] = [];

    public static get cache() {
        return Assets.cache['_cache'];
    }

    public static load(config: AssetLoaderConfig, onProgressChange?: ((perc: number) => void)): Promise<Record<string, unknown>>;
    public static load(config: IAssetConfig, onProgressChange?: ((perc: number) => void)): Promise<Record<string, unknown>>;
    public static load(config: IAssetConfig | AssetLoaderConfig, onProgressChange?: ((perc: number) => void)): Promise<Record<string, unknown>> {
        if (onProgressChange) {
            this.onProgressChange = onProgressChange;
        }

        if (AssetManager.isIAssetConfig(config)) {
            return AssetManager.loadAssetsFromConfig(undefined, config);
        } else {
            return Assets.load(config, this.onAssetLoaded.bind(this));
        }
    }

    private static isIAssetConfig(config: IAssetConfig | AssetLoaderConfig): config is IAssetConfig {
        return (config as IAssetConfig).baseUrl !== undefined;
    }

    private static setupLazyLoadAssets(assets: LazyAssetKeys, config: IAssetConfig) {
        const newConfig: IAssetConfig = {
            ...config,
            assetList: {}
        };

        const assetKeys = Object.keys(assets) as Array<keyof typeof assets>;
        assetKeys.forEach((assetKey) => {
            const assetList = config.assetList[assetKey];
            const keys = assets[assetKey];
            if (keys) {
                keys.forEach((key) => {
                    const asset = (assetList as IBaseAssetConfig[])?.find((a) => a.name === key);
                    if (asset) {
                        (newConfig.assetList[assetKey] as unknown) = newConfig.assetList[assetKey] ?? [];
                        (newConfig.assetList[assetKey] as unknown[])?.push(asset);
                    }
                });
            }
        });
        return newConfig;
    }

    private static async loadAssetsFromConfig(assets: LazyAssetKeys | undefined, config: IAssetConfig): Promise<Record<string, any>> {
        const isLazyLoad = !!assets;
        const delayedConfig = AssetManager.fixDependentAssets(config);
        const configToLoad: IAssetConfig = isLazyLoad ? this.setupLazyLoadAssets(assets, config) : config;
        const assetListKeys = Object.keys(configToLoad.assetList) as Array<keyof IAssetList & string>;
        
        assetListKeys.forEach((key) => {
            const data = configToLoad.assetList[key];
            const isDataAnArray = data !== undefined && data instanceof Array;

            if (!isDataAnArray) {
                return;
            }
        });

        if ((delayedConfig.assetList.animations && delayedConfig.assetList.animations.length > 0) || (delayedConfig.assetList.spriteSheets && delayedConfig.assetList.spriteSheets.length > 0)) {
            await this.retrieveAssets(config, isLazyLoad);
            return AssetManager.load(delayedConfig);
        } else {
            return this.retrieveAssets(config, isLazyLoad);
        }
    }

    private static async retrieveAssets(config: IAssetConfig, isLazyLoad: boolean, onProgressChange: ((perc: number) => void) | null = null): Promise<Record<string, any>> {
        this.onProgressChange = onProgressChange;
        const cdnUrl = config.baseUrl + (config.skin ? config.skin + '/' : '') + (config.version ? config.version + '/' : '');
        const toLoad: UnresolvedAsset[] = [];

        const parseFunc = (assets?:IBaseAssetConfig[], keyList?: string[]) => {
            if (!assets) { return; }

            assets.forEach((asset: IBaseAssetConfig) => {
                toLoad.push({ src: cdnUrl + asset.url, alias: asset.name });
                if (keyList) {
                    keyList.push(asset.name);
                }
            });
        };

        parseFunc(config.assetList.animations);
        parseFunc(config.assetList.spriteSheets);
        parseFunc(config.assetList.data);
        parseFunc(config.assetList.textures, this.textureKeys);

        const result = await Promise.all([
            Assets.load(toLoad, this.onAssetLoaded.bind(this)),
            SoundLoader.load(cdnUrl, config.assetList.sounds ?? [], isLazyLoad)
        ]);

        return result;
    }

    /** modifies file names in dependancies to avoid name clashes and follow a standard */
    private static fixDependentAssets(originalConfig: IAssetConfig): IAssetConfig {
        const delayedConfig: IAssetConfig = {
            baseUrl: originalConfig.baseUrl,
            skin: originalConfig.skin,
            version: originalConfig.version,
            assetList: {}
        };

        const delayedSpriteSheets: ISpriteSheetAssetConfig[] = [];
        const currentSpriteSheets: ISpriteSheetAssetConfig[] = [];

        const delayedAnimations: IAnimationAssetConfig[] = [];
        const currentAnimations: IAnimationAssetConfig[] = [];
        
        originalConfig.assetList.animations?.forEach((asset) => {
            if (asset.dependencies !== undefined) {
                if (!this.hasAsset(asset.dependencies[0].name)) {
                    //rename the textures in the atlas so they are (asset.name + '_atlas_page_' + filename)
                    if (asset.dependencies && asset.dependencies[0].dependencies) {
                        asset.dependencies[0].dependencies.forEach((texture) => {
                            const texturePath = texture.url.split('/');
                            texture.name = asset.name + '_atlas_page_' + texturePath[texturePath.length - 1];
                        });
                    }
                    AssetManager.addSpriteSheetIfNotExist(originalConfig, asset.dependencies[0]);
                    delayedAnimations.push(asset);
                } else {
                    currentAnimations.push(asset);
                }
            } else {
                currentAnimations.push(asset);
            }
        });

        if (originalConfig.assetList.spriteSheets) {
            originalConfig.assetList.spriteSheets.forEach((asset) => {
                const names: string[] = [];
                if (asset.dependencies) {
                    asset.dependencies.forEach((value) => {
                        names.push(value.name);
                    });
                }

                if (asset.dependencies !== undefined) {
                    let isDelayed: boolean = false;
                    asset.dependencies.forEach((value) => {
                        if (!this.hasAsset(value.name)) {
                            if (!originalConfig.assetList.textures) {
                                originalConfig.assetList.textures = [];
                            }
                            originalConfig.assetList.textures?.push(value);
                            isDelayed = true;
                        }
                    });
                    if (isDelayed) {
                        delayedSpriteSheets.push(asset);
                    } else {
                        currentSpriteSheets.push(asset);
                    }
                } else {
                    currentSpriteSheets.push(asset);
                }
            });
        }

        originalConfig.assetList.spriteSheets = currentSpriteSheets;
        delayedConfig.assetList.spriteSheets = delayedSpriteSheets;

        originalConfig.assetList.animations = currentAnimations;
        delayedConfig.assetList.animations = delayedAnimations;

        return delayedConfig;
    }

    private static addSpriteSheetIfNotExist(config: IAssetConfig, atlas: ISpriteSheetAssetConfig): void {
        if (config.assetList.spriteSheets === undefined) {
            config.assetList.spriteSheets = [];
            config.assetList.spriteSheets.push(atlas);
            return;
        } else {
            const exists = config.assetList.spriteSheets.some((value) => {
                return value.name === atlas.name;
            });

            if (!exists) {
                config.assetList.spriteSheets.push(atlas);
            }
        }
    }

    private static onAssetLoaded(progress: number): void {
        if (AssetManager.onProgressChange) {
            AssetManager.onProgressChange(progress);
        }
    }

    public static hasAsset(assetName: string): boolean {
        return Assets.get(assetName) !== undefined;
    }

    /**
     * Sets an asset in the asset cache as if it was loaded naturally
     * 
     * Useful for debugging something like strings by setting assets manually. Will override any pre-existing data.
     * @param assetName key within the cache to set
     * @param asset the asset to set
     */
    public static setAsset(assetName: string, asset: unknown): void {
        Assets.cache.set(assetName, asset);
    }

    /**
     * pulls the requested textures from Assets, any not found will be returned as undefined
     * @returns an array of Texture | undefined
     */
    public static getTextures(): Array<Texture | undefined> {
        return this.textureKeys.map(key => Assets.get(key));
    }

    /**
     * @deprecated avoid using as assumes the atlasName of the spine matches key + 'atlas' which may be incorrect, retained for bingo backwards compatibility
     * 
     * Use `getTextureFromAtlas` instead.
     * @param key the name of the spine to pull the texture from
     * @param textureName the name of the texture to pull
     */
    public static getSpineTexture<SpineKey extends string = string>(key: SpineKey, textureName: string): Texture {
        return this.getTextureFromAtlas({ atlas: key + 'atlas', texture: textureName });
    }

    /**
     * Returns the requested texture from a given Atlas file
     * @param texture the name of the texture to pull
     * @param atlas the atlas to pull the texture from
     */
    public static getTextureFromAtlas(options: { texture: string; atlas: string; }): Texture {
        const spineAtlas = Assets.get<TextureAtlas>(options.atlas);
        const matchedRegion = spineAtlas.regions.find((region) => region.name.toLowerCase() === options.texture.toLowerCase());

        if (!matchedRegion) {
            throw new Error(`Could not find texture with name "${options.texture}" in atlas "${options.atlas}"`);
        }

        return matchedRegion.texture;
    }

    /** Parses and returns SkeletonData for a given spine asset, caches the for future requests
     * @param skeletonName The name of the skeleton resource as defined in the asset list
     * @param atlasName Optional: The name of the atlas resource as defined in the asset list. If not provided, it is assumed to be skeletonName + 'Atlas'
     * @returns The SkeletonData for the given skeleton name
     */
    public static getSpineData<SpineKey extends string = string>(skeletonName: SpineKey, atlasName?: string) {
        // Check the cache first
        if (AssetManager.skeletonCache[skeletonName]) {
            return AssetManager.skeletonCache[skeletonName];
        }

        const skeletonAsset = Assets.get(skeletonName);
        if (skeletonAsset === undefined) {
            throw new Error(`Asset ${skeletonName} not found`);
        }

        const atlasAssetName = atlasName ?? skeletonName + 'Atlas';
        const atlasAsset = Assets.get<TextureAtlas>(atlasAssetName);
        if (atlasAsset === undefined) {
            throw new Error(`Atlas ${atlasAssetName} not found, referenced by spine ${skeletonName}`);
        }

        const attachmentLoader = new AtlasAttachmentLoader(atlasAsset);
        const parser = skeletonAsset instanceof Uint8Array
            ? new SkeletonBinary(attachmentLoader)
            : new SkeletonJson(attachmentLoader);
        parser.scale = 1;
        const skeletonData = parser.readSkeletonData(skeletonAsset);

        // cache the parsed data to avoid doing it again
        AssetManager.skeletonCache[skeletonName] = skeletonData;
        return skeletonData;
    }

    public static getSpritesheet<SpritesheetKey extends string = string>(key: SpritesheetKey): Spritesheet {
        return Assets.get<Spritesheet>(key);
    }

    public static getTexture<TextureKey extends string = string>(key: TextureKey) {
        return Assets.get<Texture>(key);
    }

    public static getBitmapFont<BitmapFontKey extends string = string>(key: BitmapFontKey): BitmapFont {
        return Assets.get<BitmapFont>(key);
    }

    public static getJsonData<T>(name: string): T {
        return Assets.get<T>(name);
    }
}